    def convert(value_str, u_in, u_out):
        v = Decimal(value_str)
        # Define hierarchy for volume: m3(3) > dm3(2) > cm3(1)
        # Define hierarchy for capacity: L(2) > mL(1)
        # Cross mapping: dm3=L(2), cm3=mL(1)

