def solve(top_view_desc, left_view_desc):
    # 1. 解析俯视图 (Top View) -> 确定底面坐标 (x, y)
    if top_view_desc == "2×2的方块":
        top_coords = [(0,0), (1,0), (0,1), (1,1)]
        ys_present = {0, 1}
    elif top_view_desc == "3个横排的方块":
        top_coords = [(0,0), (1,0), (2,0)]
        ys_present = {0}
    elif top_view_desc == "L形的3个方块":
        top_coords = [(0,0), (1,0), (0,1)]
        ys_present = {0, 1}
    else:
        raise ValueError("Unsupported top view")

    # 2. 解析左视图 (Left View) -> 确定每一行 y 的最大高度限制
    left_h_map = {}

    if left_view_desc == "竖排3格的长条":
        for y in ys_present:
            left_h_map[y] = 3

    elif left_view_desc == "竖排2格的长条":
        for y in ys_present:
            left_h_map[y] = 2

    elif left_view_desc == "下层2格上层1格靠左的形状":
        if 0 in ys_present:
            left_h_map[0] = 2
        if 1 in ys_present:
            left_h_map[1] = 1

    # 3. 计算最多数量 (Max)
    max_cubes = 0
    for x, y in top_coords:
        h_limit = left_h_map.get(y, 1)
        max_cubes += h_limit

    # 4. 计算最少数量 (Min)
    min_cubes = 0
    y_groups = {}
    for x, y in top_coords:
        if y not in y_groups:
            y_groups[y] = []
        y_groups[y].append(x)

    for y, xs in y_groups.items():
        target_h = left_h_map.get(y, 1)
        count_in_row = len(xs)
        row_min = target_h + (count_in_row - 1) * 1
        min_cubes += row_min

    return [min_cubes, max_cubes]

