        if isinstance(view, dict):
            keys = sorted(view.keys())
            if len(keys) == 2 and keys[1] - keys[0] == 1:
                if all(v == 1 for v in view.values()):
                    return True
        elif isinstance(view, set):
            if len(view) == 2:
                pts = list(view)
                (x1, y1), (x2, y2) = pts
                if abs(x1-x2) + abs(y1-y2) == 1:
                    return True
        return False

    def is_shape_B(view):
        if isinstance(view, dict):
            keys = sorted(view.keys())
            if len(keys) == 2 and keys[1] - keys[0] == 1:
                if sum(view.values()) == 3:
                    vals = sorted(view.values())
                    if vals == [1, 2]:
                        return True
        elif isinstance(view, set):
            if len(view) == 3:
                xs = [p[0] for p in view]
                ys = [p[1] for p in view]
                if max(xs)-min(xs) <= 1 and max(ys)-min(ys) <= 1:
                     return True
        return False

    matches = []
    for idx, fig in enumerate(figures_data):
