    groups = ['足球', '戏曲', '书法']

    possibilities = {n: set(groups) for n in names}
    possibilities[name_c] = {group_z}

    if group_x in possibilities[name_a]:
        possibilities[name_a].discard(group_x)

    if group_y in possibilities[name_b]:
        possibilities[name_b].discard(group_y)

    remaining_groups = [g for g in groups if g != group_z]

    p_na = possibilities[name_a] & set(remaining_groups)
    p_nb = possibilities[name_b] & set(remaining_groups)

    final_assignment = {name_c: group_z}

    if len(p_na) == 1:
        g_a = list(p_na)[0]
        final_assignment[name_a] = g_a
        g_b = [g for g in remaining_groups if g != g_a][0]
        final_assignment[name_b] = g_b
    elif len(p_nb) == 1:
        g_b = list(p_nb)[0]
        final_assignment[name_b] = g_b
        g_a = [g for g in remaining_groups if g != g_b][0]
        final_assignment[name_a] = g_a
    else:
        for ga in remaining_groups:
            gb = [g for g in remaining_groups if g != ga][0]
            if ga != group_x and gb != group_y:
                final_assignment[name_a] = ga
