def solve(context, chart_a_name, chart_b_name, chart_c_name, goal, specific_data_desc):
    goal_to_chart = {
        '数量的增减变化趋势': '折线统计图',
        '各部分占总体的百分比': '扇形统计图',
        '各个项目的具体数量多少': '条形统计图'
    }

    desc_to_chart = {
        '具体的数值大小': '条形统计图',
        '某一部分所占的比例': '扇形统计图',
        '数据随时间的变化幅度': '折线统计图'
    }

    target_chart_1 = goal_to_chart[goal]
    target_chart_2 = desc_to_chart[specific_data_desc]

    options = {'A': chart_a_name, 'B': chart_b_name, 'C': chart_c_name}

    letter_1 = None
    letter_2 = None
    for k, v in options.items():
        if v == target_chart_1:
            letter_1 = k
        if v == target_chart_2:
            letter_2 = k

    return [letter_1, letter_2]

